-- UNTESTED: no PostgreSQL in the build sandbox. CI job "migrations" applies 0001+0002 and must pass before this is trusted.
-- Not yet wired to the application (the running app uses the in-memory store). Secrets: *_enc columns hold AES-256-GCM blobs only.
BEGIN;
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, workspace_id uuid REFERENCES workspaces(id), name text NOT NULL, website text, industry text, locale text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE brands (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, business_id uuid NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name text NOT NULL, voice jsonb, guidelines jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE knowledge_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, brand_id uuid REFERENCES brands(id) ON DELETE CASCADE, kind text NOT NULL, body text NOT NULL, source text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE capability_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version int NOT NULL UNIQUE, sha256 text NOT NULL, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_definitions (id text PRIMARY KEY, role text NOT NULL, division text, tool_allowlist text[] NOT NULL, budget jsonb NOT NULL);
CREATE TABLE model_providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, provider text NOT NULL, api_key_enc text, allow_paid boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (org_id, provider));
CREATE TABLE tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, capability_id text REFERENCES capabilities(id), status text NOT NULL DEFAULT 'queued', payload jsonb NOT NULL, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, task_id uuid REFERENCES tasks(id), agent_id text NOT NULL, status text NOT NULL, tokens int NOT NULL DEFAULT 0, model_label text, trace jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE research_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, business_id uuid REFERENCES businesses(id), title text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE research_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, project_id uuid NOT NULL REFERENCES research_projects(id) ON DELETE CASCADE, url text NOT NULL, fetched_at timestamptz, untrusted_excerpt text);
CREATE TABLE research_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, project_id uuid NOT NULL REFERENCES research_projects(id) ON DELETE CASCADE, claim text NOT NULL, source_id uuid REFERENCES research_sources(id), confidence text);
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, business_id uuid REFERENCES businesses(id), name text NOT NULL, objective text, status text NOT NULL DEFAULT 'draft', budget_cents bigint, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE content_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, campaign_id uuid REFERENCES campaigns(id), kind text NOT NULL, title text, body text, status text NOT NULL DEFAULT 'draft', approval_id uuid REFERENCES approvals(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, kind text NOT NULL, storage_key text NOT NULL, mime text NOT NULL, bytes bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE social_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, platform text NOT NULL, handle text NOT NULL, oauth_grant_id uuid, UNIQUE (org_id, platform, handle));
CREATE TABLE social_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, account_id uuid REFERENCES social_accounts(id), content_id uuid REFERENCES content_items(id), scheduled_for timestamptz, status text NOT NULL DEFAULT 'draft', approval_id uuid REFERENCES approvals(id));
CREATE TABLE ad_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, campaign_id uuid REFERENCES campaigns(id), platform text NOT NULL, daily_budget_cents bigint NOT NULL CHECK (daily_budget_cents >= 0), status text NOT NULL DEFAULT 'draft', approval_id uuid REFERENCES approvals(id));
CREATE TABLE seo_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, business_id uuid REFERENCES businesses(id), domain text NOT NULL, keywords jsonb, audits jsonb);
CREATE TABLE contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, email text, phone text, name text, lifecycle text NOT NULL DEFAULT 'lead', score int, source text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE consents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, contact_id uuid NOT NULL REFERENCES contacts(id) ON DELETE CASCADE, channel text NOT NULL, granted boolean NOT NULL, evidence text, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, definition jsonb NOT NULL, enabled boolean NOT NULL DEFAULT false);
CREATE TABLE workflow_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, workflow_id uuid NOT NULL REFERENCES workflows(id) ON DELETE CASCADE, status text NOT NULL, log jsonb, started_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, connector_id text NOT NULL, status text NOT NULL, UNIQUE (org_id, connector_id));
CREATE TABLE oauth_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, connector_id text NOT NULL, secret_enc text NOT NULL, scopes text[] NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE sync_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, connector_id text NOT NULL, direction text NOT NULL, status text NOT NULL, detail text, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agency_clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, portal_user_id uuid REFERENCES users(id));
CREATE TABLE deliverables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, client_id uuid REFERENCES agency_clients(id), title text NOT NULL, status text NOT NULL DEFAULT 'draft', approval_id uuid REFERENCES approvals(id));
CREATE TABLE autonomy_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, action_classes text[] NOT NULL, max_spend_per_action_cents bigint NOT NULL, max_spend_total_cents bigint NOT NULL, spent_cents bigint NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, granted_by uuid REFERENCES users(id));
CREATE TABLE usage_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, kind text NOT NULL, provider text, model text, tokens_in int NOT NULL DEFAULT 0, tokens_out int NOT NULL DEFAULT 0, may_incur_charge boolean NOT NULL, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotas (org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, metric text NOT NULL, limit_value bigint NOT NULL, PRIMARY KEY (org_id, metric));
CREATE TABLE system_health (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), component text NOT NULL, status text NOT NULL, detail text, at timestamptz NOT NULL DEFAULT now());
-- Tenant isolation: enable RLS + policy on every table that has org_id (app must SET LOCAL app.org_id per request).
DO $$ DECLARE t text; BEGIN
  FOR t IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='org_id' AND table_name NOT IN ('approvals','audit_events','memberships') LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (org_id = current_setting(''app.org_id'', true)::uuid)', t);
  END LOOP; END $$;
COMMIT;
